mapper.update:
UPDATE sys_chat_message
SET recalled = 1, recalled_time = NOW(), content = #{placeholder},
    is_read = 1, read_time = IFNULL(read_time, NOW())
WHERE message_id = #{messageId}
  AND session_id = #{sessionId}
  AND sender_id = #{senderId}
  AND msg_type = 'TEXT'
  AND recalled = 0
  AND created_at >= #{windowStart}

UPDATE sys_chat_message
SET is_read = 1, read_time = #{readTime}
WHERE session_id = #{sessionId}
  AND receiver_id = #{receiverId}
  AND is_read = 0

UPDATE sys_chat_message SET is_read = 1, read_time = #{readTime}
WHERE session_id = #{sessionId} AND sender_id = #{userId}
  AND message_id <= #{throughMessageId} AND is_read = 0
